// The Wiring: rotate tiles to carry power from the socket to the lamp.
// Generated by growing a random tree of wires over the grid first, then scrambling
// every tile, so there is always an answer.

import { W, H, room } from '../scenery.js';
import * as L from '../light.js';
import { timerSecs } from '../run.js';

const N = 1, E = 2, S = 4, Wb = 8;
const DIRS = [[N, 0, -1, S], [E, 1, 0, Wb], [S, 0, 1, N], [Wb, -1, 0, E]];
export const rotate = (m, k) => { for (let i = 0; i < k; i++) m = ((m << 1) | (m >> 3)) & 15; return m; };

export function generate(n) {
  const size = n * n;
  const base = new Array(size).fill(0);
  const seen = new Array(size).fill(false);
  const socket = Math.floor(Math.random() * n) * n;          // a cell on the left edge
  const stack = [socket];
  seen[socket] = true;
  while (stack.length) {
    const i = stack[stack.length - 1];
    const x = i % n, y = Math.floor(i / n);
    const opts = DIRS.filter(([, dx, dy]) => {
      const nx = x + dx, ny = y + dy;
      return nx >= 0 && ny >= 0 && nx < n && ny < n && !seen[ny * n + nx];
    });
    if (!opts.length) { stack.pop(); continue; }
    const [bit, dx, dy, back] = opts[Math.floor(Math.random() * opts.length)];
    const j = (y + dy) * n + x + dx;
    base[i] |= bit; base[j] |= back; seen[j] = true; stack.push(j);
  }
  // the lamp goes on the far right, at the cell furthest along the wires from the socket
  const dist = reach(base, n, socket, true);
  let lampCell = n - 1, far = -1;
  for (let y = 0; y < n; y++) { const i = y * n + n - 1; if (dist[i] > far) { far = dist[i]; lampCell = i; } }
  let rot;
  do { rot = base.map(() => Math.floor(Math.random() * 4)); } while (connected(base.map((m, i) => rotate(m, rot[i])), n, socket, lampCell));
  return { base, rot, socket, lamp: lampCell };
}

// Distance from `from` along matching wires (-1 where power does not reach).
export function reach(masks, n, from, distances = false) {
  const d = new Array(n * n).fill(-1);
  d[from] = 0;
  const q = [from];
  while (q.length) {
    const i = q.shift();
    const x = i % n, y = Math.floor(i / n);
    for (const [bit, dx, dy, back] of DIRS) {
      if (!(masks[i] & bit)) continue;
      const nx = x + dx, ny = y + dy;
      if (nx < 0 || ny < 0 || nx >= n || ny >= n) continue;
      const j = ny * n + nx;
      if (d[j] >= 0 || !(masks[j] & back)) continue;
      d[j] = d[i] + 1; q.push(j);
    }
  }
  return distances ? d : d;
}

export const connected = (masks, n, a, b) => reach(masks, n, a)[b] >= 0;

function layout(n) {
  const cell = Math.min(56, 300 / n);
  const size = cell * n;
  return { cell, x: W / 2 - size / 2, y: 340 - size / 2, size };
}

export default {
  id: 'wiring',
  start({ depth, run, dark }) {
    const n = depth <= 2 ? 4 : depth <= 5 ? 5 : 6;
    const p = generate(n);
    const total = timerSecs(run, 55 + n * 9);
    return { n, ...p, total, left: total, t: 0, done: 0, warned: false, events: [], run, dark: dark ? 5 : 0, spin: new Array(n * n).fill(0) };
  },

  masks(s) { return s.base.map((m, i) => rotate(m, s.rot[i])); },

  update(s, dt, input) {
    s.t += dt;
    s.dark = Math.max(0, s.dark - dt);
    for (let i = 0; i < s.spin.length; i++) s.spin[i] = Math.max(0, s.spin[i] - dt * 8);
    if (s.done) { s.done += dt; return s.done > 1.1 ? 'won' : 'playing'; }
    s.left -= dt;
    if (!s.warned && s.left < s.total * 0.25) { s.warned = true; s.events.push({ warn: true }); }
    if (s.left <= 0) return 'lost';
    const g = layout(s.n);
    for (const tap of input.taps) {
      const c = Math.floor((tap.x - g.x) / g.cell), r = Math.floor((tap.y - g.y) / g.cell);
      if (c < 0 || r < 0 || c >= s.n || r >= s.n) continue;
      const i = r * s.n + c;
      s.rot[i] = (s.rot[i] + 1) % 4;
      s.spin[i] = 1;
      s.events.push({ sfx: 'turn', x: tap.x });
      if (connected(this.masks(s), s.n, s.socket, s.lamp)) { s.done = 0.001; s.events.push({ sfx: 'power' }); }
    }
    return 'playing';
  },

  timer(s) { return 1 - s.left / s.total; },

  draw(s, t) {
    const ctx = L.begin(0);
    const n = s.n, g = layout(n);
    const masks = this.masks(s);
    const live = reach(masks, n, s.socket);
    const p = Math.min(1, 1 - s.left / s.total);
    room(ctx, t);
    ctx.fillStyle = 'rgba(0,0,0,0.45)'; ctx.fillRect(0, 0, W, H);
    // the board
    ctx.fillStyle = '#1a110c'; ctx.fillRect(g.x - 14, g.y - 30, g.size + 28, g.size + 44);
    ctx.fillStyle = '#26170f'; ctx.fillRect(g.x - 8, g.y - 8, g.size + 16, g.size + 16);
    // the fuse along the top: burns from left to right
    const fy = g.y - 20;
    ctx.strokeStyle = '#5a4a3a'; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(g.x + g.size * p, fy); ctx.lineTo(g.x + g.size, fy); ctx.stroke();
    ctx.strokeStyle = '#1a1210'; ctx.beginPath(); ctx.moveTo(g.x, fy); ctx.lineTo(g.x + g.size * p, fy); ctx.stroke();
    // which tile a hint points at: the first wrong tile on the way from socket to lamp
    let hint = -1;
    if (s.run.mods.hint && !s.done) {
      const pathD = reach(s.base, n, s.socket, true);
      let i = s.lamp;
      const path = [i];
      while (i !== s.socket) {
        const x = i % n, y = Math.floor(i / n);
        const prev = DIRS.map(([bit, dx, dy]) => ((s.base[i] & bit) ? (y + dy) * n + x + dx : -1)).find((j) => j >= 0 && pathD[j] === pathD[i] - 1);
        if (prev === undefined) break;
        path.push(prev); i = prev;
      }
      hint = path.reverse().find((k) => masks[k] !== s.base[k]) ?? -1;
    }
    for (let i = 0; i < n * n; i++) {
      const x = g.x + (i % n) * g.cell, y = g.y + Math.floor(i / n) * g.cell;
      ctx.fillStyle = '#100a07'; ctx.fillRect(x + 1, y + 1, g.cell - 2, g.cell - 2);
      const cx = x + g.cell / 2, cy = y + g.cell / 2;
      const on = live[i] >= 0;
      ctx.save(); ctx.translate(cx, cy); ctx.rotate(-s.spin[i] * Math.PI / 2);
      ctx.strokeStyle = on ? '#f0b35a' : '#6a4a32';
      ctx.lineWidth = g.cell * 0.16; ctx.lineCap = 'round';
      ctx.beginPath();
      for (const [bit, dx, dy] of DIRS) if (masks[i] & bit) { ctx.moveTo(0, 0); ctx.lineTo(dx * g.cell / 2, dy * g.cell / 2); }
      ctx.stroke();
      ctx.fillStyle = on ? '#f0b35a' : '#6a4a32';
      ctx.beginPath(); ctx.arc(0, 0, g.cell * 0.1, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
      if (i === s.socket) { ctx.fillStyle = '#d9cfb4'; ctx.fillRect(cx - g.cell * 0.18, cy - g.cell * 0.14, g.cell * 0.36, g.cell * 0.28); ctx.fillStyle = '#1a1210'; ctx.fillRect(cx - g.cell * 0.08, cy - g.cell * 0.06, 2, 4); ctx.fillRect(cx + g.cell * 0.05, cy - g.cell * 0.06, 2, 4); }
      if (i === s.lamp) { ctx.fillStyle = s.done ? '#fff1d0' : '#5a4e40'; ctx.beginPath(); ctx.arc(cx, cy, g.cell * 0.2, 0, Math.PI * 2); ctx.fill(); }
      if (i === hint) { ctx.strokeStyle = 'rgba(232,224,202,0.8)'; ctx.lineWidth = 1.5; ctx.setLineDash([3, 3]); ctx.strokeRect(x + 3, y + 3, g.cell - 6, g.cell - 6); ctx.setLineDash([]); }
    }
    const lampX = g.x + (s.lamp % n + 0.5) * g.cell, lampY = g.y + (Math.floor(s.lamp / n) + 0.5) * g.cell;
    const sparkX = g.x + g.size * p;
    const flare = s.run.mods.light;
    L.dark(s.dark > 0 ? 0.985 : (s.done ? 0.3 : 0.72 - flare * 0.12));
    if (s.dark <= 0) {
      L.hole(W / 2, g.y + g.size / 2, (g.size * 0.75) * (1 + flare * 0.25), 0.75);
      for (let i = 0; i < n * n; i++) if (live[i] >= 0) L.hole(g.x + (i % n + 0.5) * g.cell, g.y + (Math.floor(i / n) + 0.5) * g.cell, g.cell * 0.8, 0.45);
      L.hole(sparkX, fy, 40, 0.8);
      if (s.done) L.hole(lampX, lampY, 320 * Math.min(1, s.done * 2), 1);
    }
    L.lay();
    if (p < 1 && !s.done) { L.glow(sparkX, fy, 10, [255, 180, 90], 0.9); }
    if (s.done) L.glow(lampX, lampY, 60, [255, 240, 210], 0.7);
    return L.end();
  },
};
